-- 此表的上游涉及太多需要人来维护的地方，因此需要把上游做成快照表，以此来缓冲各种回刷数据的诉求。
-- part1 获取rcmd不同场景的bundle信息
-- https://docs.google.com/spreadsheets/d/1rCbwEn86ekz0q235peOBi74PpM5LFhNGxAW0SNOkVUg/edit?usp=sharing
create temporary view bundle_mapping_${grass_region_without_quote} as
select cast(scene_id as bigint) as scene_id
      ,scene_key
      ,bundle
      ,algo_tag
      ,feature_group
      ,cast(cover_scene_id as bigint) as cover_scene_id
      ,cover_scene_key
from srdi_mart.ods_sr_data_warehouse_abtest_rcmd_scene_bundle_mapping
where grass_date=${local_date} and ingestion_timestamp = (select max(ingestion_timestamp) from srdi_mart.ods_sr_data_warehouse_abtest_rcmd_scene_bundle_mapping where grass_date=${local_date})
;
--sql_divide_splitter--

create temporary view rcmd_scene_bundle_mapping_${grass_region_without_quote} as
select t1.scene_id
      ,t1.scene_key
      ,named_struct('bundle', t2.bundle, 'algo_tag', t2.algo_tag) as bundle_algo_tag_struct
from (
    select scene_id
          ,scene_key
          ,cover_scene_id
    from bundle_mapping_${grass_region_without_quote}
    where cover_scene_id > 0 -- 普通的rcmd scene, 但是有点特殊, 当前只有mixrank scene比较特殊, 会额外绑定dd + pp, 后续可能存在绑定scene变化, 或者出现新增类似mixrank的scene
) t1 
left join (
    select scene_id
          ,bundle
          ,algo_tag
          ,feature_group
    from bundle_mapping_${grass_region_without_quote}
    where cover_scene_id is null  -- 普通的rcmd scene
) t2 on t1.cover_scene_id = t2.scene_id
 
union all

select scene_id
      ,scene_key
      ,named_struct('bundle', bundle, 'algo_tag', algo_tag) as bundle_algo_tag_struct
from bundle_mapping_${grass_region_without_quote}
where cover_scene_id is null
;
--sql_divide_splitter--
-- part2 获取rcmd 目前我们关注的场景和优先层 对应的 algo_tags
create temporary view rcmd_scene_layer_${grass_region_without_quote} as
select cast(scene_id as bigint) as scene_id
      ,scene_key
      ,cast(priority_layer_id as bigint) as priority_layer_id
from srdi_mart.ods_sr_data_warehouse_abtest_rcmd_scene_layer
where grass_date=${local_date} and ingestion_timestamp = (select max(ingestion_timestamp) from srdi_mart.ods_sr_data_warehouse_abtest_rcmd_scene_layer where grass_date=${local_date})
;
--sql_divide_splitter--

create temporary view normal_scene_${grass_region_without_quote} as
select t1.scene_id
      ,map_from_entries(collect_set(t2.bundle_algo_tag_struct)) as normal_scene_bundle_algo_tag_map
from (
    select scene_id
          ,scene_key
    from rcmd_scene_layer_${grass_region_without_quote}
    where priority_layer_id is null -- 非优先层
) t1 
left join rcmd_scene_bundle_mapping_${grass_region_without_quote} t2 on t1.scene_id = t2.scene_id
group by t1.scene_id
;
--sql_divide_splitter--

create temporary view priority_layer_related_scene_${grass_region_without_quote} as
select scene_id
      ,priority_layer_id
      ,map_from_entries(collect_set(bundle_algo_tag_struct)) as priority_layer_related_scene_algo_tag_map
from (
    select t1.scene_id
          ,t1.priority_layer_id
          ,t3.bundle_algo_tag_struct
    from (
        select scene_id
              ,priority_layer_id
        from rcmd_scene_layer_${grass_region_without_quote}     -- 优先层
        where priority_layer_id is not null
    ) t1 
    left join ( -- 对这个绑定关系表做ods快照存储，防止内容变化后，导致回刷数据有问题，
        select scene_id
              ,layer_id
              ,related_scene_id 
        from srdi_mart.ods_sr_data_warehouse_priority_layer_relation_tab
        where regional_date=${local_date} and valid = 1
        group by scene_id, layer_id, related_scene_id
    ) t2 on t1.scene_id = t2.scene_id and t1.priority_layer_id = t2.layer_id
    left join rcmd_scene_bundle_mapping_${grass_region_without_quote} t3 on t2.related_scene_id = t3.scene_id
) t 
group by scene_id, priority_layer_id
;
--sql_divide_splitter--
