-- part3 获取exp对应的实验组信息
--
-- bundle存在3种来源
-- experiment yaml config scopes, 这块在推进废弃
-- experiment parameter_tab_bundles
-- lyaer traffic_condition_bundles
-- scene defult_banding_bundles
--
-- scene -> layer -> experiment 逐级递进的关系, bundle生效的优先级是反过来的, exp配置最高优;
-------------------------------------------------------------
create temporary view experiment_info_${grass_region_without_quote} as
-- 这个上游表中的时间和状态等，我们并未用来处理逻辑，暂时不做ods层
select scene_id
      ,project_id
      ,layer_id
      ,id as experiment_id
      ,valid
      ,start_time
      ,end_time
      ,creator
      ,update_pic
      ,experiment_status
      ,experiment_mode
      ,log_switch
      ,use_parameter_tabs
      ,parameter_tabs
      ,array_distinct( -- 实验level的参数改变因该并不会很频繁
        flatten(
          transform(
               from_json(parameter_tabs, 'array<struct<fmt_filter_expression:string>>')
             , e->regexp_extract_all(e.fmt_filter_expression, 'bundle == "([^"]+)"', 1)
          )
        )
      ) as parameter_tab_bundles
from abtest.shopee_experiment_admin_db__experiment_tab__reg_continuous_s0_live
;
--sql_divide_splitter--

create temporary view layer_info_${grass_region_without_quote} as
-- 这个表是layer level的实验信息，很可能会中途修改，这个表也需要做ods 快照存储
select id as layer_id
      --,priority -- share, normal, union, associate = 30000,priority=500
      ,scene_id
      ,array_distinct(
         regexp_extract_all(fmt_filter_expression, 'bundle == "([^"]+)"', 1)
       ) as layer_traffic_condition_bundles
from srdi_mart.ods_sr_data_warehouse_experiment_layer_tab
where regional_date=${local_date}
;
--sql_divide_splitter--

create temporary view join_all_info_${grass_region_without_quote} as
select experiment_id
      ,layer_id
      ,project_id
      ,scene_id
       
      ,start_time
      ,end_time
      ,creator
      ,update_pic
      ,experiment_status
      ,experiment_mode
      ,log_switch
      ,use_parameter_tabs
      ,parameter_tabs
        
      ,valid
      ,is_rcmd_normal_scene
      ,is_rcmd_priority_layer
 
      ,parameter_tab_bundles
      ,layer_traffic_condition_bundles
      ,scene_bundle_algo_tag_map

      ,transform(
          filter(parameter_tab_bundles, e -> scene_bundle_algo_tag_map[e] IS NOT NULL)
         ,f->scene_bundle_algo_tag_map[f]
       ) as parameter_tab_algo_tags
      ,transform(
          filter(layer_traffic_condition_bundles, e -> scene_bundle_algo_tag_map[e] IS NOT NULL)
         ,f->scene_bundle_algo_tag_map[f]
       ) as layer_traffic_condition_algo_tags

      ,transform(map_entries(scene_bundle_algo_tag_map), e->e.value) as scene_algo_tags 
from (
    select t1.scene_id
          ,t1.project_id
          ,t1.layer_id
          ,t1.experiment_id
          ,t1.valid
          ,t1.start_time
          ,t1.end_time
          ,t1.creator
          ,t1.update_pic
          ,t1.experiment_status
          ,t1.experiment_mode
          ,t1.log_switch
          ,t1.use_parameter_tabs
          ,t1.parameter_tabs
           
          ,t1.parameter_tab_bundles
          ,t4.layer_traffic_condition_bundles --这里没有限制我们关注的，所以有些我们不关注的也会有值
          ,if(t2.normal_scene_bundle_algo_tag_map is not null, 1, 0) as is_rcmd_normal_scene
          ,if(t3.priority_layer_related_scene_algo_tag_map is not null, 1, 0) as is_rcmd_priority_layer
          ,if(t3.priority_layer_related_scene_algo_tag_map is not null, t3.priority_layer_related_scene_algo_tag_map, t2.normal_scene_bundle_algo_tag_map) as scene_bundle_algo_tag_map
    from experiment_info_${grass_region_without_quote} t1
    left join normal_scene_${grass_region_without_quote} t2 on t1.scene_id = t2.scene_id
    left join priority_layer_related_scene_${grass_region_without_quote} t3 on t1.scene_id = t3.scene_id and t1.layer_id = t3.priority_layer_id
    left join layer_info_${grass_region_without_quote} t4 on t1.scene_id = t4.scene_id and t1.layer_id = t4.layer_id
) t 
;
--sql_divide_splitter--
-- part4 获取 experiment 实际生效的实验场景 对应的 algo_tags
insert overwrite table ${schema}.dim_sr_data_warehouse_abtest_experiment partition(regional_date = ${local_date})
select experiment_id
      ,layer_id
      ,project_id
      ,scene_id
     
      ,start_time
      ,end_time
      ,creator
      ,update_pic
      ,experiment_status
      ,experiment_mode
      ,log_switch
      ,use_parameter_tabs
      ,parameter_tabs
      
      ,valid
      ,is_rcmd_normal_scene
      ,is_rcmd_priority_layer
 
      ,parameter_tab_bundles
      ,layer_traffic_condition_bundles
      ,scene_bundle_algo_tag_map
 
      ,parameter_tab_algo_tags
      ,layer_traffic_condition_algo_tags
      ,scene_algo_tags 
      ,if(is_rcmd_normal_scene=1 or is_rcmd_priority_layer=1 -- 只允许我们关注的有值，防止干扰其余实验
          ,case
            when size(parameter_tab_algo_tags) > 0           then parameter_tab_algo_tags
            when size(layer_traffic_condition_algo_tags) > 0 then layer_traffic_condition_algo_tags
            when size(scene_algo_tags) > 0                   then scene_algo_tags
           end
          ,null) as exp_algo_tags
      ,if(is_rcmd_normal_scene=1 or is_rcmd_priority_layer=1
          ,case
             when size(parameter_tab_algo_tags) > 0 then size(scene_algo_tags)-size(parameter_tab_algo_tags)
             when size(layer_traffic_condition_algo_tags) > 0 then size(scene_algo_tags)-size(layer_traffic_condition_algo_tags)
             else 0
           end
         ,0) as scenarios_diff
from join_all_info_${grass_region_without_quote}
;
